1	//! API key authentication middleware — *who* the caller is.
2	//!
3	//! Checks the `Authorization` header for any of:
4	//! - `Authorization: ApiKey <key>`
5	//! - `Authorization: Bearer <key>`
6	//! - `Authorization: Basic <base64(user:pass)>`
7	//!
8	//! When `config.auth.enabled` is `false` (or `--insecure` mode was set by
9	//! clearing the key), the check is skipped entirely.
10	//!
11	//! Authentication answers *who*; [`crate::authz`] answers *what they may
12	//! touch*. The bridge between them is [`Principal`], produced here by
13	//! [`authenticate`] and consulted there. `is_authorized` — the boolean the
14	//! gRPC interceptor and the HTTP middleware share — is now a thin wrapper over
15	//! `authenticate`, so the two surfaces cannot drift.
16	
17	use axum::{
18	    extract::{FromRequestParts, Request, State},
19	    http::{request::Parts, StatusCode},
20	    middleware::Next,
21	    response::{IntoResponse, Response},
22	    Json,
23	};
24	use xerj_engine::rbac::{Privilege, Role};
25	
26	use crate::error::{EsErrorBody, EsErrorResponse, EsRootCause};
27	use crate::state::AppState;
28	
29	// ─────────────────────────────────────────────────────────────────────────────
30	
31	/// Probe endpoints exempted from authentication.
32	///
33	/// `/health/live` and `/health/ready` are the conventional Kubernetes liveness
34	/// and readiness paths that container `HEALTHCHECK`s (see `engine/Dockerfile`)
35	/// and Helm chart probes hit **without** credentials. Gating them behind auth
36	/// makes every hardened deployment crashloop: the moment `auth.enabled = true`,
37	/// the kubelet's probe (and Docker's `curl -fsS .../health/ready`) receives a
38	/// 401, is marked unhealthy, and the pod is restarted forever. Both handlers
39	/// are dependency-free and expose no index data (they answer a bare
40	/// `"live"`/`"ready"` string), so leaving them open is safe.
41	pub const AUTH_EXEMPT_PATHS: [&str; 2] = ["/health/live", "/health/ready"];
42	
43	/// Is `path` the share-claim route, `/_share/claim`?
44	///
45	/// The one unauthenticated route that hands out a credential: a guest who
46	/// opens a share link has, by definition, no key yet. It is exempted the way
47	/// `/v1/metrics` is for the scrape token — by exact path, `POST` only (the
48	/// method check is the caller's), never by prefix — and the handler
49	/// (`crate::share::claim_share`) rate-limits per source address and per share
50	/// and audits every outcome. Everything else under `/_share` stays behind
51	/// authentication and is superuser-only in its handler.
52	///
53	/// The share id is in the request **body**. The first cut matched
54	/// `/_share/{id}/claim`, which put the id into every access log between the
55	/// guest and the node; that shape is deliberately not exempt any more, so a
56	/// stale client gets a plain `401` instead of a second, id-leaking way in.
57	pub fn is_share_claim_path(path: &str) -> bool {
58	    let mut segs = path.split('/').filter(|s| !s.is_empty());
59	    matches!(
60	        (segs.next(), segs.next(), segs.next()),
61	        (Some("_share"), Some("claim"), None)
62	    )
63	}
64	
65	// ─────────────────────────────────────────────────────────────────────────────
66	// Principal
67	// ─────────────────────────────────────────────────────────────────────────────
68	
69	/// The authenticated identity behind a request.
70	///
71	/// Authentication used to collapse to a bool, which is exactly why a brain was
72	/// not a security boundary: with no principal on the request there was nothing
73	/// for an authorization check to consult (issue #79). Every variant below is a
74	/// *capability statement*, and the ordering is deliberate — the further down
75	/// the list, the less a caller may reach.
76	#[derive(Clone, Debug, PartialEq, Eq)]
77	pub enum Principal {
78	    /// Full access. Two ways to be one, and only two:
79	    /// - **open mode** — `auth.enabled = false` or no admin key configured.
80	    ///   This is `xerj --insecure` and the point-at-a-folder first run, where
81	    ///   there is exactly one user and no configuration; it must keep working
82	    ///   with zero setup, so it is deliberately unrestricted.
83	    /// - the configured **admin/superuser key** (`auth.admin_api_key`).
84	    Superuser,
85	    /// A key minted by `POST /_security/api_key` **with** usable
86	    /// `role_descriptors`. Confined: it may touch only the indices its roles
87	    /// name, and nothing that is not index-scoped.
88	    Scoped {
89	        /// The minted key's id (for audit/log lines, never compared).
90	        key_id: String,
91	        /// Index grants parsed from `role_descriptors`. Never empty — an
92	        /// empty grant list is [`Principal::Unscoped`].
93	        roles: Vec<Role>,
94	    },
95	    /// A key minted **without** `role_descriptors` — the shape every key had
96	    /// before per-brain authorization existed.
97	    ///
98	    /// It keeps its historical reach over the general ES-compat surface (so
99	    /// hardened Kibana/Beats deployments do not break), but it holds **no**
100	    /// privilege on the reserved `.xerj-memory-*` namespace. That is the
101	    /// fail-closed half: an unconfigured principal is denied the brain, not
102	    /// granted it.
103	    Unscoped {
104	        /// The minted key's id.
105	        key_id: String,
106	    },
107	    /// No valid credential. Normally unreachable inside a handler — the auth
108	    /// middleware answers 401 first — but it is what the [`Principal`]
109	    /// extractor yields if a handler is ever mounted without that middleware,
110	    /// so the default is "deny", never "allow".
111	    Denied,
112	}
113	
114	impl Principal {
115	    /// Does this principal hold `privilege` on `index`?
116	    ///
117	    /// This is the single authorization predicate; [`crate::authz`] routes
118	    /// every enforcement point through it. `Unscoped` answers `true` for
119	    /// ordinary indices (its historical reach) and `false` for the reserved
120	    /// namespace, which [`crate::authz::is_reserved_index`] defines.
121	    pub fn allows_index(&self, index: &str, privilege: Privilege) -> bool {
122	        match self {
123	            Principal::Superuser => true,
124	            Principal::Scoped { roles, .. } => roles.iter().any(|r| r.allows(index, privilege)),
125	            Principal::Unscoped { .. } => !crate::authz::is_reserved_index(index),
126	            Principal::Denied => false,
127	        }
128	    }
129	
130	    /// Is this the key a share-link claim minted (`crate::share::claim_share`)?
131	    ///
132	    /// Such a key carries exactly one role, named `share:<handle>`. It is
133	    /// recognised by that name and nothing else, which is safe in the only
134	    /// direction that matters: being recognised as a guest only ever *removes*
135	    /// reach ([`crate::authz`] intersects the guest route allow-list with the
136	    /// key's index grants — it never adds to them). An operator who mints an
137	    /// ordinary key with a role descriptor called `share:x` gets a key that is
138	    /// more confined than they asked for, never less.
139	    pub fn is_share_guest(&self) -> bool {
140	        match self {
141	            Principal::Scoped { roles, .. } => {
142	                !roles.is_empty()
143	                    && roles
144	                        .iter()
145	                        .all(|r| r.name.starts_with(crate::share::GUEST_ROLE_PREFIX))
146	            }
147	            _ => false,
148	        }
149	    }
150	
151	    /// True for the one principal that is allowed to see and do everything —
152	    /// used to skip the authorization work entirely on the local-dev path.
153	    pub fn is_superuser(&self) -> bool {
154	        matches!(self, Principal::Superuser)
155	    }
156	
157	    /// Short identity string for error/log lines. Never contains key material.
158	    pub fn label(&self) -> &str {
159	        match self {
160	            Principal::Superuser => "superuser",
161	            Principal::Scoped { key_id, .. } | Principal::Unscoped { key_id } => key_id.as_str(),
162	            Principal::Denied => "unauthenticated",
163	        }
164	    }
165	}
166	
167	/// Extract the principal straight from the request's `Authorization` header.
168	///
169	/// Deliberately *re-derives* rather than reading a request extension planted
170	/// by the middleware: a handler that authorizes must be safe by construction
171	/// even if it is mounted on a router where the middleware was forgotten. The
172	/// cost is one map lookup plus a constant-time compare. When no credential
173	/// resolves, the result is [`Principal::Denied`] — never an error that a
174	/// caller could turn into a bypass.
175	#[axum::async_trait]
176	impl FromRequestParts<AppState> for Principal {
177	    type Rejection = std::convert::Infallible;
178	
179	    async fn from_request_parts(
180	        parts: &mut Parts,
181	        state: &AppState,
182	    ) -> Result<Self, Self::Rejection> {
183	        let header = parts
184	            .headers
185	            .get(axum::http::header::AUTHORIZATION)
186	            .and_then(|v| v.to_str().ok());
187	        Ok(authenticate(state, header))
188	    }
189	}
190	
191	/// Axum middleware that enforces API key authentication.
192	///
193	/// Call via `middleware::from_fn_with_state(state, auth_middleware)` in the
194	/// router builders.
195	pub async fn auth_middleware(State(state): State<AppState>, req: Request, next: Next) -> Response {
196	    // Kubernetes / Docker probes must stay reachable without credentials, or a
197	    // hardened (auth-enabled) deployment crashloops. See `AUTH_EXEMPT_PATHS`.
198	    if AUTH_EXEMPT_PATHS.contains(&req.uri().path()) {
199	        return next.run(req).await;
200	    }
201	
202	    // RC4-W4 item 4: optional read-only metrics token. When configured, a
203	    // caller presenting the exact token may scrape `/v1/metrics` — and ONLY
204	    // that endpoint — without the admin key, so Prometheus can be handed a
205	    // low-privilege scrape credential that cannot read index data. The admin
206	    // key still works for metrics via the normal path below.
207	    if req.uri().path() == "/v1/metrics" && metrics_token_authorized(&state, &req) {
208	        return next.run(req).await;
209	    }
210	
211	    // A guest claiming a share link has no credential yet — that is the
212	    // whole point of the route. See `is_share_claim_path`.
213	    if req.method() == axum::http::Method::POST && is_share_claim_path(req.uri().path()) {
214	        return next.run(req).await;
215	    }
216	
217	    // Xerj Console lives in a peer router (mounted by `xerj-server` via
218	    // `Router::merge`) and runs its own session-cookie auth, so this
219	    // middleware never sees `/_xerj-console/*` requests — no path-prefix
220	    // bypass needed.
221	
222	    // Extract the Authorization header.
223	    let auth_header = req
224	        .headers()
225	        .get(axum::http::header::AUTHORIZATION)
226	        .and_then(|v| v.to_str().ok());
227	
228	    if is_authorized(&state, auth_header) {
229	        next.run(req).await
230	    } else {
231	        unauthorized_response(&state.config.server.data_dir)
232	    }
233	}
234	
235	/// The shared authorization decision, enforced identically by the HTTP
236	/// `auth_middleware` and the gRPC auth interceptor (`xerj-server::grpc`) so both
237	/// API surfaces require the same credentials.
238	///
239	/// Returns `true` when the request may proceed:
240	/// - auth is disabled, or no admin key is configured (open mode — matches the
241	///   `--insecure` / first-run posture); or
242	/// - the `Authorization` value carries the configured admin/superuser key
243	///   (as `ApiKey <key>`/`Bearer <key>`, or as the password half of
244	///   `Basic <base64(user:pass)>`); or
245	/// - it carries a key minted by `POST /_security/api_key`, as either
246	///   `ApiKey <base64(id:api_key)>` or `Basic <base64(id:api_key)>` — Kibana's
247	///   interactive "basic" realm login sends the latter, and a minted key's
248	///   `id:secret` shape is already exactly `user:pass`.
249	///
250	/// `auth_header` is the raw `Authorization` header / `authorization` metadata
251	/// value (e.g. `"ApiKey abc"`, `"Bearer abc"`, or `"Basic base64(...)"`), or
252	/// `None` when absent.
253	pub fn is_authorized(state: &AppState, auth_header: Option<&str>) -> bool {
254	    !matches!(authenticate(state, auth_header), Principal::Denied)
255	}
256	
257	/// Resolve the request's credential to a [`Principal`].
258	///
259	/// Same acceptance rules as [`is_authorized`] (which is now defined in terms of
260	/// this), but it reports *which* identity authenticated so authorization has
261	/// something to decide against. Returns [`Principal::Denied`] when nothing
262	/// authenticates.
263	pub fn authenticate(state: &AppState, auth_header: Option<&str>) -> Principal {
264	    let cfg = &state.config.auth;
265	
266	    // Open mode: auth disabled or no admin key configured. This is the
267	    // `--insecure` / point-at-a-folder posture — one user, no configuration —
268	    // and it stays fully unrestricted on purpose.
269	    if !cfg.enabled || cfg.admin_api_key.is_empty() {
270	        return Principal::Superuser;
271	    }
272	
273	    let Some(header) = auth_header else {
274	        return Principal::Denied;
275	    };
276	
277	    if let Some(key) = extract_key(header) {
278	        // The configured admin/superuser key. Compared in constant time
279	        // (item 7): a plain `==` short-circuits on the first mismatching byte,
280	        // leaking the shared-secret prefix length via response timing. The
281	        // created-key path already used `constant_time_eq`; the admin key —
282	        // the single most valuable credential in the system — must not be
283	        // weaker. `constant_time_eq` still returns early on a length mismatch,
284	        // which only reveals the key *length*, matching the created-key path.
285	        if constant_time_eq(key.as_bytes(), cfg.admin_api_key.as_bytes()) {
286	            return Principal::Superuser;
287	        }
288	        // A key minted by `POST /_security/api_key`.
289	        return authenticate_api_key(state, key);
290	    }
291	
292	    basic_principal(state, header)
293	}
294	
295	/// Validate `Authorization: Basic <base64(user:pass)>`.
296	///
297	/// xerj has no per-username credential store — same single-owner identity
298	/// model `security_authenticate` already uses — so this doesn't check the
299	/// username against anything. Two things are accepted as the *password*
300	/// half, both already valid credentials via the `ApiKey`/`Bearer` schemes:
301	/// - the admin/superuser key (any username — mirrors ES's own "elastic"
302	///   bootstrap superuser, where the secret is what's checked, not the name);
303	/// - or, treating the whole decoded `user:pass` as `id:secret`, a key minted
304	///   by `POST /_security/api_key` (its `id:secret` shape already matches
305	///   `user:pass` exactly, so no separate encoding is needed here).
306	fn basic_principal(state: &AppState, header: &str) -> Principal {
307	    let Some(prefix) = header.get(..6) else {
308	        return Principal::Denied;
309	    };
310	    if !prefix.eq_ignore_ascii_case("basic ") {
311	        return Principal::Denied;
312	    }
313	    let encoded = header[6..].trim();
314	    let decoded = match crate::es_compat::base64_decode(encoded) {
315	        Some(d) => d,
316	        None => return Principal::Denied,
317	    };
318	    let decoded = match std::str::from_utf8(&decoded) {
319	        Ok(s) => s,
320	        Err(_) => return Principal::Denied,
321	    };
322	    let Some((user, pass)) = decoded.split_once(':') else {
323	        return Principal::Denied;
324	    };
325	
326	    let cfg = &state.config.auth;
327	    if constant_time_eq(pass.as_bytes(), cfg.admin_api_key.as_bytes()) {
328	        return Principal::Superuser;
329	    }
330	    check_minted_key(state, user, pass)
331	}
332	
333	/// Decide whether a request to `/v1/metrics` may proceed on the strength of
334	/// the read-only `auth.metrics_token` alone (RC4-W4 item 4).
335	///
336	/// Returns `false` (falls through to normal auth) when the token is unset or
337	/// the presented credential doesn't match it. The comparison is constant-time,
338	/// matching the admin-key path — a scrape token is still a shared secret.
339	fn metrics_token_authorized(state: &AppState, req: &Request) -> bool {
340	    let token = &state.config.auth.metrics_token;
341	    if token.is_empty() {
342	        return false;
343	    }
344	    req.headers()
345	        .get(axum::http::header::AUTHORIZATION)
346	        .and_then(|v| v.to_str().ok())
347	        .and_then(extract_key)
348	        .map(|k| constant_time_eq(k.as_bytes(), token.as_bytes()))
349	        .unwrap_or(false)
350	}
351	
352	/// Re-authenticate a created API key credential.
353	///
354	/// The presented value is `base64("id:api_key")`. Decode it, split on the
355	/// first `':'`, look the id up in the engine's key store, and constant-time
356	/// compare the secret. The resulting principal carries the key's stored
357	/// grants: [`Principal::Scoped`] when it was minted with usable
358	/// `role_descriptors`, [`Principal::Unscoped`] otherwise.
359	fn authenticate_api_key(state: &AppState, presented: &str) -> Principal {
360	    let decoded = match crate::es_compat::base64_decode(presented) {
361	        Some(d) => d,
362	        None => return Principal::Denied,
363	    };
364	    let decoded = match std::str::from_utf8(&decoded) {
365	        Ok(s) => s,
366	        Err(_) => return Principal::Denied,
367	    };
368	    let (id, secret) = match decoded.split_once(':') {
369	        Some(parts) => parts,
370	        None => return Principal::Denied,
371	    };
372	    check_minted_key(state, id, secret)
