375	/// Look up a minted `POST /_security/api_key` credential by `(id, secret)`.
376	/// Shared by the `ApiKey <base64(id:secret)>` and `Basic <base64(id:secret)>`
377	/// paths — both decode to the same `id:secret` shape.
378	///
379	/// A minted key is **never** a superuser: the strongest thing it can be is
380	/// `Unscoped`, which has no reach into the reserved `.xerj-memory-*`
381	/// namespace. That is what stops "any authenticated caller reads any brain".
382	fn check_minted_key(state: &AppState, id: &str, secret: &str) -> Principal {
383	    let record = match state.engine.api_keys.get(id) {
384	        Some(r) => r,
385	        None => return Principal::Denied,
386	    };
387	    if record.invalidated {
388	        return Principal::Denied;
389	    }
390	    if let Some(exp) = record.expiration_ms {
391	        let now_ms = chrono::Utc::now().timestamp_millis().max(0) as u64;
392	        if now_ms >= exp {
393	            return Principal::Denied;
394	        }
395	    }
396	    // Issue #201: the stored form is a salted SHA-256 digest, not the
397	    // credential. `verify_secret` hashes the presented secret under the
398	    // record's salt and compares digests in constant time, and answers `false`
399	    // for any record it cannot make sense of — an unmigrated or mangled record
400	    // denies rather than falling back to a plaintext compare.
401	    if !record.verify_secret(secret) {
402	        return Principal::Denied;
403	    }
404	    if record.roles.is_empty() {
405	        Principal::Unscoped {
406	            key_id: id.to_string(),
407	        }
408	    } else {
409	        Principal::Scoped {
410	            key_id: id.to_string(),
411	            roles: record.roles.clone(),
412	        }
413	    }
414	}
