416	/// Length-independent-only constant-time byte comparison. Avoids leaking the
417	/// secret via early-exit timing once lengths match.
418	fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
419	    if a.len() != b.len() {
420	        return false;
421	    }
422	    let mut diff = 0u8;
423	    for (x, y) in a.iter().zip(b.iter()) {
424	        diff |= x ^ y;
425	    }
426	    diff == 0
427	}
