433	/// Extract the raw key from an `Authorization` header value.
434	///
435	/// Accepts both `ApiKey <key>` and `Bearer <key>` schemes (case-insensitive
436	/// scheme prefix).
437	fn extract_key(header: &str) -> Option<&str> {
438	    let lower = header.to_ascii_lowercase();
439	    if lower.starts_with("apikey ") {
440	        Some(header["ApiKey ".len()..].trim())
441	    } else if lower.starts_with("bearer ") {
442	        Some(header["Bearer ".len()..].trim())
443	    } else {
444	        None
445	    }
446	}
