448	/// The `WWW-Authenticate` challenge sent with every 401.
449	///
450	/// RFC 7235 §3.1 makes the header **mandatory** on a 401, and Elasticsearch
451	/// sends one; xerj sent none, so a conforming client (or a human running `curl
452	/// -i`) got a 401 with no statement of *how* to authenticate.
453	///
454	/// The scheme name is `ApiKey` because that is a scheme this server genuinely
455	/// honours — [`extract_key`] accepts `ApiKey <key>` (and `Bearer <key>`), and
456	/// it is the one every xerj client actually writes: the autoindex HTTP client
457	/// sends `Authorization: ApiKey <key>`, and `xerj.default.toml` documents
458	/// exactly that spelling beside `[auth] enabled = true`. `Bearer` and `Basic`
459	/// are deliberately **not** advertised even though both authenticate:
460	/// advertising `Basic` makes browsers pop a username/password dialog for a
461	/// credential that has no username half, and one challenge naming the
462	/// canonical scheme is more useful to a newcomer than three naming synonyms.
463	pub const WWW_AUTHENTICATE_CHALLENGE: &str = "ApiKey realm=\"xerj\"";
464	
465	/// Build an ES-compatible 401 Unauthorized response.
466	///
467	/// `data_dir` is the server's configured data directory, threaded in from
468	/// `state.config.server.data_dir` so the body can name the **real**
469	/// `admin.key` path rather than a `<data_dir>` placeholder. xerj has no config
470	/// discovery and `data_dir` defaults to the *relative* `./data`, so the key
471	/// lands wherever the server happened to be launched from — "where is my key?"
472	/// is genuinely unanswerable from the client side, and a placeholder would not
473	/// have answered it.
474	///
475	/// The ES error envelope (`security_exception`, `root_cause`, `status`) is a
476	/// wire-compat surface with a conformance suite behind it: only the free-text
477	/// `reason` changes here, never a field name or the structure.
478	fn unauthorized_response(data_dir: &str) -> Response {
479	    let key_path = std::path::Path::new(data_dir)
480	        .join("admin.key")
481	        .display()
482	        .to_string();
483	    let reason = format!(
484	        "missing or invalid API key in Authorization header. \
485	         Send `Authorization: ApiKey <key>`. This server writes its admin key to {key_path} \
486	         on first start, so `export XERJ_API_KEY=\"$(cat {key_path})\"` (every xerj CLI reads \
487	         that variable, `xerj autoindex` included) or pass `--api-key <key>`. \
488	         To run with no authentication at all — local development only — restart the server \
489	         with `--insecure`, which disables TLS *and* auth."
490	    );
491	    let error_type = "security_exception".to_string();
492	
493	    let body = EsErrorResponse {
494	        error: EsErrorBody {
495	            root_cause: vec![EsRootCause {
496	                error_type: error_type.clone(),
497	                reason: reason.clone(),
498	                resource_type: None,
499	                resource_id: None,
500	                index_uuid: None,
501	                index: None,
502	            }],
503	            error_type,
504	            reason,
505	            resource_type: None,
506	            resource_id: None,
507	            index_uuid: None,
508	            index: None,
509	            request_id: None,
510	        },
511	        status: 401,
512	        xerj_hint: None,
513	    };
514	
515	    (
516	        StatusCode::UNAUTHORIZED,
517	        [(
518	            axum::http::header::WWW_AUTHENTICATE,
519	            WWW_AUTHENTICATE_CHALLENGE,
520	        )],
521	        Json(body),
522	    )
523	        .into_response()
524	}
