954	    /// Kibana's interactive "basic" realm login authenticates to ES via
955	    /// `Authorization: Basic base64(user:pass)`, not `ApiKey`/`Bearer` — this
956	    /// is what let the login form work at all once xerj started requiring
957	    /// auth. Any username is accepted as long as the password is the admin
958	    /// key (mirrors ES's own "elastic" bootstrap superuser), and a minted
959	    /// `POST /_security/api_key` credential also works via Basic since its
960	    /// `id:secret` shape already IS `user:pass`.
961	    #[tokio::test]
962	    async fn basic_auth_accepts_admin_password_and_minted_key() {
963	        let admin = "admin-secret-key-0123456789abcdef";
964	        let state = test_state(admin);
965	        let app = app(state.clone());
966	
967	        // Any username, password = admin key.
968	        let hdr = format!(
969	            "Basic {}",
970	            crate::es_compat::base64_encode(&format!("kibana_system:{admin}"))
971	        );
