976	            "Basic {}",
977	            crate::es_compat::base64_encode("kibana_system:wrong-password")
978	        );
979	        assert!(!is_authorized(&state, Some(&bad_hdr)));
980	
981	        // Malformed input never panics: bad base64, no colon, too-short
982	        // header, and an empty credential all just fail authorization.
983	        assert!(!is_authorized(&state, Some("Basic %%%not-base64%%%")));
984	        assert!(!is_authorized(
985	            &state,
986	            Some(&format!(
987	                "Basic {}",
988	                crate::es_compat::base64_encode("no-colon-here")
989	            ))
990	        ));
991	        assert!(!is_authorized(&state, Some("Bas")));
992	        assert!(!is_authorized(&state, Some("Basic ")));
