997	        let admin_hdr = format!("ApiKey {admin}");
998	        let (status, body) = send(
999	            &app,
1000	            "POST",
1001	            "/_security/api_key",
1002	            Some(&admin_hdr),
1003	            r#"{"name":"kibana"}"#,
1004	        )
1005	        .await;
1006	        assert_eq!(status, StatusCode::OK);
