1008	        let secret = body["api_key"].as_str().unwrap().to_string();
1009	        let minted_basic_hdr = format!(
1010	            "Basic {}",
1011	            crate::es_compat::base64_encode(&format!("{id}:{secret}"))
1012	        );
1013	        let (status, _) = send(
1014	            &app,
1015	            "GET",
1016	            "/_security/_authenticate",
1017	            Some(&minted_basic_hdr),
1018	            "",
1019	        )
1020	        .await;
1021	        assert_eq!(status, StatusCode::OK, "minted key via Basic should work");
