1079	    /// RFC 7235 §3.1: a 401 **must** carry a `WWW-Authenticate` challenge, and
1080	    /// the scheme it names must be one this server actually honours. xerj sent
1081	    /// none, so a client that got a 401 was told it was unauthenticated and
1082	    /// nothing about how to fix that (ONBOARDING-401-REPRO.md).
1083	    ///
1084	    /// The advertised scheme is proved honoured *here*, in the same test, so
1085	    /// the header can never drift into naming something the middleware
1086	    /// rejects: the challenge's scheme name is spliced onto the admin key and
1087	    /// must authenticate.
1088	    #[tokio::test]
1089	    async fn unauthorized_carries_a_www_authenticate_challenge() {
1090	        let admin = "admin-secret-key";
1091	        let state = test_state(admin);
1092	        let app = app(state.clone());
1093	
1094	        let req = Request::builder()
1095	            .method("GET")
1096	            .uri("/_security/_authenticate")
1097	            .body(Body::empty())
1098	            .unwrap();
1099	        let resp = app.clone().oneshot(req).await.unwrap();
1100	        assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
1101	
1102	        let challenge = resp
1103	            .headers()
1104	            .get(axum::http::header::WWW_AUTHENTICATE)
1105	            .expect("401 must carry WWW-Authenticate (RFC 7235 §3.1)")
1106	            .to_str()
1107	            .expect("challenge must be printable ASCII")
1108	            .to_string();
1109	        assert_eq!(challenge, WWW_AUTHENTICATE_CHALLENGE);
1110	        assert!(
1111	            challenge.contains(r#"realm="xerj""#),
1112	            "challenge must carry a realm, got {challenge:?}"
1113	        );
1114	
1115	        // The named scheme is a scheme the server genuinely accepts.
1116	        let scheme = challenge
1117	            .split_whitespace()
1118	            .next()
1119	            .expect("challenge names a scheme");
1120	        assert!(
1121	            is_authorized(&state, Some(&format!("{scheme} {admin}"))),
1122	            "advertised scheme {scheme:?} must authenticate the admin key"
1123	        );
1124	
1125	        // A rejected *credential* gets the challenge too, not just a missing
1126	        // one — the client needs to be told how to retry either way.
1127	        let req = Request::builder()
1128	            .method("GET")
1129	            .uri("/_security/_authenticate")
1130	            .header("authorization", "ApiKey not-the-key")
1131	            .body(Body::empty())
1132	            .unwrap();
1133	        let resp = app.oneshot(req).await.unwrap();
1134	        assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
1135	        assert_eq!(
1136	            resp.headers()
1137	                .get(axum::http::header::WWW_AUTHENTICATE)
1138	                .and_then(|v| v.to_str().ok()),
1139	            Some(WWW_AUTHENTICATE_CHALLENGE),
1140	            "a rejected key must be challenged too"
1141	        );
1142	    }
