1144	    /// The 401 body must name the recovery, and must keep the ES error
1145	    /// envelope byte-compatible while doing it. The old `reason` was accurate
1146	    /// and useless — a newcomer following the shipped `xerj.default.toml`
1147	    /// (which enables auth) read "missing or invalid API key" and concluded
1148	    /// their server lacked a feature, then disabled auth.
1149	    ///
1150	    /// The real `admin.key` path is threaded in from the server's own config,
1151	    /// not a `<data_dir>` placeholder: `data_dir` defaults to the *relative*
1152	    /// `./data`, so the key lands wherever the server was launched from and a
1153	    /// placeholder answers nothing.
1154	    #[tokio::test]
1155	    async fn unauthorized_body_names_the_recovery() {
1156	        let admin = "admin-secret-key";
1157	        let state = test_state(admin);
