1167	        assert_eq!(body["error"]["type"], "security_exception");
1168	        assert_eq!(body["error"]["root_cause"][0]["type"], "security_exception");
1169	        let reason = body["error"]["reason"].as_str().expect("reason string");
1170	        assert_eq!(
1171	            body["error"]["root_cause"][0]["reason"], reason,
1172	            "root_cause reason must mirror the top-level reason"
1173	        );
1174	
1175	        // The recovery, named. Each of these is a thing the user must type.
1176	        let expected_path = std::path::Path::new(&data_dir)
1177	            .join("admin.key")
1178	            .display()
1179	            .to_string();
1180	        assert!(
1181	            reason.contains(&expected_path),
1182	            "reason must name this server's real admin.key path ({expected_path}), got {reason:?}"
1183	        );
1184	        assert!(
1185	            reason.contains("XERJ_API_KEY"),
1186	            "reason must name the env var, got {reason:?}"
1187	        );
1188	        assert!(
1189	            reason.contains("--insecure"),
1190	            "reason must name the explicit auth opt-out, got {reason:?}"
1191	        );
1192	        assert!(
1193	            reason.contains("ApiKey"),
1194	            "reason must name the scheme to send, got {reason:?}"
