1153	/// Resolves an alias to the indices behind it.
1154	///
1155	/// Authorization consults this **before** deciding, so `POST /pwned/_search`
1156	/// on an alias pointed at someone else's brain is authorized against that
1157	/// brain, not against the alias name. `Engine::get_index` resolves aliases too
1158	/// and re-checks after doing so, which is what covers an alias created between
1159	/// the decision and the read.
1160	pub trait AliasResolver {
1161	    fn targets(&self, name: &str) -> Option<Vec<String>>;
1162	}
1163	
1164	impl AliasResolver for AppState {
1165	    fn targets(&self, name: &str) -> Option<Vec<String>> {
1166	        self.engine.aliases.get(name).map(|e| e.value().clone())
1167	    }
1168	}
