1415	];
1416	/// The same, for the ops that take a document id as one further segment.
1417	///
1418	/// `_source` was on this list and in the docs' "a guest can" table, but the
1419	/// router has no `/{index}/_source/{id}` route — `404` for the admin key too
1420	/// (review of PR #947). An allow-list entry for a route that does not exist
1421	/// is a permission nobody tested; whoever adds the route decides then.
1422	const GUEST_DOC_OPS: &[&str] = &["_doc"];
1423	/// The read half of the graph API.
1424	const GUEST_GRAPH_OPS: &[&str] = &["ego", "overview"];
1425	/// Query-string parameters that turn a permitted search into something else.
1426	/// `scroll` opens a server-side cursor that outlives the request.
1427	const GUEST_DENIED_PARAMS: &[&str] = &["scroll"];
