1523	/// The guest's 403. Says what the key is for, so a guest who wandered gets an
1524	/// explanation rather than the operator-facing "mint a key whose
1525	/// role_descriptors grant…" remedy, which they can do nothing with.
1526	fn guest_forbidden(principal: &Principal, path: &str) -> Response {
1527	    tracing::debug!(
1528	        principal = principal.label(),
1529	        path,
1530	        "share-link guest denied a route outside the reading-room allow-list"
1531	    );
1532	    crate::share::no_store(es_error(
1533	        StatusCode::FORBIDDEN,
1534	        "this credential is a share-link guest key: it can search and read the shared \
1535	         index (and walk the shared brain's links), and nothing else on this node"
1536	            .to_string(),
1537	    ))
1538	}
