1186	/// `POST /_share/claim` — the guest's one call. **Unauthenticated** (see the
1187	/// module docs for why that is safe), rate-limited, audited.
1188	///
1189	/// Body: `{id, passcode}` — the share id travels in the body, never in the
1190	/// path (module docs, "The share id is never part of a request path"). On
1191	/// success: `{api_key, index, indices, brain, expires_at, label, claims_left}`
1192	/// — `api_key` is ready for `Authorization: ApiKey <api_key>`. `index` is the
1193	/// comma-joined list, which is a valid ES multi-index expression for
1194	/// `/{index}/_search`.
1195	pub async fn claim_share(
1196	    State(state): State<AppState>,
1197	    ClaimSource(source): ClaimSource,
1198	    body: Option<Json<Value>>,
1199	) -> Response {
1200	    no_store(claim_share_inner(state, source, body).await)
1201	}
1202	
1203	/// The share id a claim body names. Anything that is not a string is the
1204	/// empty id, which no share has: a body without one is answered like any other
1205	/// unknown link — charged to the source window, audited, `404`.
1206	fn claim_id(body: Option<&Value>) -> String {
1207	    body.and_then(|b| b.get("id"))
1208	        .and_then(Value::as_str)
1209	        .map(|s| s.trim().to_string())
1210	        .unwrap_or_default()
1211	}
1212	
1213	async fn claim_share_inner(state: AppState, source: String, body: Option<Json<Value>>) -> Response {
1214	    let subject = format!("guest@{source}");
1215	    let now = now_ms();
1216	    let id = claim_id(body.as_ref().map(|Json(b)| b));
1217	    if !auth_is_enforced(&state) {
1218	        return open_node_refusal();
1219	    }
1220	    // The lookup comes FIRST, and which window is charged depends on its
1221	    // answer — see "The two throttles" in the module docs. It is a SHA-256 and
1222	    // a map probe, so an unauthenticated caller buys nothing by forcing it.
1223	    let Some(record) = state.shares.find_by_id(&id) else {
1224	        // Junk: the source window is the only throttle there is. Behind a
1225	        // tunnel every client shares the loopback bucket, which makes this
1226	        // bound tighter, never looser — and it cannot lock a real guest out,
1227	        // because a real share id never reaches this branch.
1228	        let bucket = format!("ip:{}", source_bucket(&source));
1229	        if let Err(t) = state
1230	            .shares
1231	            .charge(&bucket, IP_PER_MINUTE, IP_PER_HOUR, now)
1232	        {
1233	            if t.first_in_window {
1234	                state.engine.audit.append(
1235	                    "share.claim",
1236	                    &subject,
1237	                    "_share",
1238	                    "denied",
1239	                    "rate-limited (source); further refusals in this window are not logged",
1240	                );
1241	            }
1242	            return too_many(t.retry_after_secs);
1243	        }
1244	        state
1245	            .engine
1246	            .audit
1247	            .append("share.claim", &subject, "_share", "error", "unknown share");
1248	        return es_error(
1249	            StatusCode::NOT_FOUND,
1250	            "resource_not_found_exception",
1251	            "unknown share link".into(),
1252	        );
1253	    };
1254	    let handle = record.handle.clone();
1255	    // A real share: its own window, from anywhere. This is the passcode
1256	    // lockout and it holds whoever is asking and however they got here.
1257	    if let Err(t) = state.shares.charge(
1258	        &format!("share:{handle}"),
1259	        SHARE_PER_MINUTE,
1260	        SHARE_PER_HOUR,
1261	        now,
1262	    ) {
1263	        if t.first_in_window {
1264	            state.engine.audit.append(
1265	                "share.claim",
1266	                &subject,
1267	                &handle,
1268	                "denied",
1269	                "rate-limited (share); further refusals in this window are not logged",
1270	            );
1271	        }
1272	        return too_many(t.retry_after_secs);
1273	    }
1274	    if let Some(why) = record.unavailable(now) {
1275	        state
1276	            .engine
1277	            .audit
1278	            .append("share.claim", &subject, &handle, "denied", why);
1279	        return es_error(StatusCode::GONE, "share_unavailable", why.into());
1280	    }
1281	    let presented = body
1282	        .as_ref()
1283	        .and_then(|Json(b)| b.get("passcode"))
1284	        .and_then(Value::as_str)
1285	        .map(|s| s.trim().to_string())
1286	        .unwrap_or_default();
1287	    let stored = record.passcode_hash.clone();
1288	    let ok = if presented.is_empty() {
1289	        false
1290	    } else {
1291	        tokio::task::spawn_blocking(move || verify_passcode(&presented, &stored))
1292	            .await
1293	            .unwrap_or(false)
1294	    };
1295	    if !ok {
1296	        state
1297	            .engine
1298	            .audit
1299	            .append("share.claim", &subject, &handle, "denied", "wrong passcode");
1300	        state.engine.audit.sync_to_disk();
1301	        return es_error(
1302	            StatusCode::UNAUTHORIZED,
1303	            "security_exception",
1304	            "wrong passcode".into(),
1305	        );
1306	    }
1307	
1308	    // Mint the guest's key: read-only over exactly the granted indices,
1309	    // expiring with the share. Same key material shape as
1310	    // `POST /_security/api_key` so the same auth path re-authenticates it.
1311	    let granted = record.granted_indices();
1312	    let roles = vec![Role::new(
1313	        format!("{GUEST_ROLE_PREFIX}{handle}"),
1314	        HashSet::from([Privilege::ReadIndex]),
1315	        granted,
1316	    )];
1317	    let key_id = uuid::Uuid::new_v4().to_string();
1318	    let raw_secret = format!(
1319	        "{}{}",
1320	        uuid::Uuid::new_v4().simple(),
1321	        uuid::Uuid::new_v4().simple()
1322	    );
1323	    let api_key = crate::es_compat::base64_encode(&raw_secret);
1324	    let encoded = crate::es_compat::base64_encode(&format!("{key_id}:{api_key}"));
1325	    let key_record = xerj_engine::engine::ApiKeyRecord::new(
1326	        format!("share:{handle}"),
1327	        &api_key,
1328	        now,
1329	        Some(record.expires_ms),
1330	        roles,
1331	    );
1332	
1333	    // Consume the claim first, under the record lock, so two racing claims of
1334	    // a one-claim share cannot both succeed.
1335	    let claims_left = {
1336	        let Some(mut rec) = state.shares.records.get_mut(&handle) else {
1337	            return es_error(
1338	                StatusCode::NOT_FOUND,
1339	                "resource_not_found_exception",
1340	                "unknown share link".into(),
1341	            );
1342	        };
1343	        if let Some(why) = rec.unavailable(now) {
1344	            state
1345	                .engine
1346	                .audit
1347	                .append("share.claim", &subject, &handle, "denied", why);
1348	            return es_error(StatusCode::GONE, "share_unavailable", why.into());
1349	        }
1350	        rec.claims += 1;
1351	        rec.key_ids.push(key_id.clone());
1352	        rec.max_claims.saturating_sub(rec.claims)
1353	    };
1354	    if let Err(e) = state.engine.persist_api_key(key_id.clone(), key_record) {
1355	        if let Some(mut rec) = state.shares.records.get_mut(&handle) {
1356	            rec.claims = rec.claims.saturating_sub(1);
1357	            rec.key_ids.retain(|k| k != &key_id);
1358	        }
1359	        return crate::error::ApiError::new(xerj_common::XerjError::from(e)).into_response();
1360	    }
1361	    if let Err(e) = state.shares.persist() {
1362	        tracing::error!(error = %e, "could not persist shares.json after claim");
1363	    }
1364	    state.engine.audit.append(
1365	        "share.claim",
1366	        &subject,
1367	        &handle,
1368	        "ok",
1369	        &format!("key_id={key_id} claims_left={claims_left}"),
1370	    );
1371	    state.engine.audit.sync_to_disk();
1372	
1373	    Json(json!({
1374	        "api_key": encoded,
1375	        "index": record.indices.join(","),
1376	        "indices": record.indices,
1377	        "brain": record.brain,
1378	        "expires_at": rfc3339(record.expires_ms),
1379	        "label": record.label,
1380	        "claims_left": claims_left,
1381	    }))
1382	    .into_response()
1383	}
