1385	fn too_many(retry_after_secs: u64) -> Response {
1386	    let mut resp = es_error(
1387	        StatusCode::TOO_MANY_REQUESTS,
1388	        "too_many_requests",
1389	        format!("too many claim attempts; retry in {retry_after_secs}s"),
1390	    );
1391	    if let Ok(v) = header::HeaderValue::from_str(&retry_after_secs.to_string()) {
1392	        resp.headers_mut().insert(header::RETRY_AFTER, v);
1393	    }
1394	    resp
1395	}
