1514	    #[test]
1515	    fn rate_windows_lock_out_after_the_limit() {
1516	        let dir = tempfile::tempdir().unwrap();
1517	        let store = ShareStore::open(dir.path().to_str().unwrap());
1518	        let now = 1_000_000;
1519	        for _ in 0..SHARE_PER_MINUTE {
1520	            store
1521	                .charge("share:x", SHARE_PER_MINUTE, SHARE_PER_HOUR, now)
1522	                .unwrap();
1523	        }
1524	        let refused = store
1525	            .charge("share:x", SHARE_PER_MINUTE, SHARE_PER_HOUR, now)
1526	            .unwrap_err();
1527	        let retry = refused.retry_after_secs;
1528	        assert!((1..=61).contains(&retry), "{retry}");
1529	        // The first refusal in a window is the one that gets audited; the
1530	        // flood behind it is not, or the audit log becomes the attack.
1531	        assert!(refused.first_in_window);
1532	        let again = store
1533	            .charge("share:x", SHARE_PER_MINUTE, SHARE_PER_HOUR, now)
1534	            .unwrap_err();
1535	        assert!(!again.first_in_window);
1536	        // A different share is untouched.
1537	        store
1538	            .charge("share:y", SHARE_PER_MINUTE, SHARE_PER_HOUR, now)
1539	            .unwrap();
1540	        // The minute window rolls over; the hour window still counts.
1541	        //
1542	        // A minute-throttled attempt returns before the hour window is
1543	        // charged — it never reaches passcode verification, so it is not a
1544	        // guess and does not spend the hourly guess budget. Filling the hour
1545	        // therefore takes *accepted* charges, spread over fresh minute windows.
1546	        let mut t = now;
1547	        let mut accepted = SHARE_PER_MINUTE;
1548	        while accepted < SHARE_PER_HOUR {
1549	            t += WINDOW_MIN_MS + 1;
1550	            for _ in 0..SHARE_PER_MINUTE {
1551	                if accepted == SHARE_PER_HOUR {
1552	                    break;
1553	                }
1554	                store
1555	                    .charge("share:x", SHARE_PER_MINUTE, SHARE_PER_HOUR, t)
1556	                    .unwrap();
1557	                accepted += 1;
1558	            }
1559	        }
1560	        // The hourly budget is spent. A brand-new minute window does not help.
1561	        t += WINDOW_MIN_MS + 1;
1562	        assert!(t - now < WINDOW_HOUR_MS, "still inside the same hour");
1563	        let retry = store
1564	            .charge("share:x", SHARE_PER_MINUTE, SHARE_PER_HOUR, t)
1565	            .unwrap_err()
1566	            .retry_after_secs;
1567	        assert!(
1568	            retry > 60,
1569	            "locked out by the hour window, not the minute one: {retry}s"
1570	        );
1571	        // And the throttled attempts above never counted as guesses.
1572	        assert_eq!(accepted, SHARE_PER_HOUR);
1573	    }
