809	fn ensure_admin_key(cfg: &mut Config) -> Result<()> {
810	    if !cfg.auth.enabled || !cfg.auth.admin_api_key.is_empty() {
811	        return Ok(());
812	    }
813	
814	    let data_dir = Path::new(&cfg.server.data_dir);
815	    let key_path = data_dir.join("admin.key");
816	
817	    // A prior run may have already persisted a key — reuse it instead of
818	    // minting a fresh one on every restart. A regenerated key on each
819	    // restart forces every client (Kibana/OSD, MCP configs, scripts) to be
820	    // manually re-pointed at the new value, which is exactly what
821	    // persisting to `admin.key` in the first place was meant to avoid.
822	    // Only a well-formed 64-char hex string (the shape this function itself
823	    // always produces) is trusted; anything else falls through to a fresh
824	    // generation rather than risk starting up with a garbled credential.
825	    if let Ok(existing) = std::fs::read_to_string(&key_path) {
826	        let existing = existing.trim();
827	        if existing.len() == 64 && existing.bytes().all(|b| b.is_ascii_hexdigit()) {
828	            cfg.auth.admin_api_key = existing.to_string();
829	            return Ok(());
830	        }
831	    }
832	
833	    // Generate 32 random bytes → 64-char hex string
834	    let raw: Vec<u8> = (0..32).map(|_| rand::random::<u8>()).collect();
835	    let key: String = raw.iter().map(|b| format!("{b:02x}")).collect();
