838	    println!("╔══════════════════════════════════════════════════╗");
839	    println!("║  First-run: admin API key auto-generated         ║");
840	    println!("║                                                  ║");
841	    println!("║  {:<48} ║", key);
842	    println!("║                                                  ║");
843	    println!("║  Keep this secret. Written to:                   ║");
844	    println!("║  {:<48} ║", format!("{}/admin.key", cfg.server.data_dir));
845	    println!("╚══════════════════════════════════════════════════╝");
846	    println!();
847	
848	    if std::fs::create_dir_all(data_dir).is_ok() {
