    body: Option<Json<Value>>,
) -> impl IntoResponse {
    if let Err(e) = validate_snapshot_repo_name(&repo) {
        return ApiError::new(e).into_response();
    }
    if let Err(e) = validate_snapshot_name(&snapshot) {
        return ApiError::new(e).into_response();
    }
    let repo_config = match state.engine.snapshot_repos.get(&repo) {
        Some(cfg) => cfg.clone(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
            return ApiError::new(e).into_response();
        }
    };

    let repo_path = repo_config
        .pointer("/settings/location")
        .and_then(Value::as_str)
        .unwrap_or("/tmp/xerj-snapshots");

    let body = body.map(|Json(b)| b).unwrap_or(Value::Null);

    // Restore options that would CHANGE what gets written (index renames,
    // per-index setting rewrites, feature states) are not implemented.
    // Fail loud rather than restoring something other than what was asked
    // for — ignoring a rename_pattern would clobber the source index.
    for unsupported in [
        "rename_pattern",
        "rename_replacement",
        "feature_states",
        "index_settings",
        "ignore_index_settings",
    ] {

    let end_ms = now_millis();

    let manifest = serde_json::json!({
        "snapshot": name,
        "uuid": uuid::Uuid::new_v4().to_string(),
        "version": "8.13.0",
        "indices": target_indices,
        "state": "SUCCESS",
        "start_time_in_millis": start_ms,
        "end_time_in_millis": end_ms,
        "duration_in_millis": (end_ms - start_ms).max(0),
        "failures": [],
        "shards": {
            "total": target_indices.len(),
            "failed": 0,
            "successful": target_indices.len(),
        },
    });

    let manifest_path = snap_dir.join("manifest.json");
    let bytes = serde_json::to_vec_pretty(&manifest).map_err(EngineError::Serde)?;
    std::fs::write(&manifest_path, bytes).map_err(EngineError::Io)?;

    info!(snapshot = name, repo = repo_path, "snapshot created");
    Ok(manifest)
}

